impl Decoder<SystemInstructionData> for SystemInstructionDataCodec {
    fn read(&self, reader: &mut Reader<'_>) -> Result<SystemInstructionData, Error> {
        let bytes = reader.remaining().get(..4).ok_or(Error::Truncated)?;
        let tag = Number::<u32>::LE.decode(bytes, solana_kit_core::codecs::Limits::new(4, 0))?;

        match tag {
            0 => Ok(SystemInstructionData::CreateAccount(
                CreateAccountCodec.read(reader)?,
            )),
            1 => Ok(SystemInstructionData::Assign(AssignCodec.read(reader)?)),
            2 => Ok(SystemInstructionData::TransferSol(
                TransferSolCodec.read(reader)?,
            )),
            3 => Ok(SystemInstructionData::CreateAccountWithSeed(
                CreateAccountWithSeedCodec.read(reader)?,
            )),
            4 => Ok(SystemInstructionData::AdvanceNonceAccount(
                AdvanceNonceAccountCodec.read(reader)?,
            )),
            5 => Ok(SystemInstructionData::WithdrawNonceAccount(
                WithdrawNonceAccountCodec.read(reader)?,
            )),
            6 => Ok(SystemInstructionData::InitializeNonceAccount(
                InitializeNonceAccountCodec.read(reader)?,
            )),
            7 => Ok(SystemInstructionData::AuthorizeNonceAccount(
                AuthorizeNonceAccountCodec.read(reader)?,
            )),
            8 => Ok(SystemInstructionData::Allocate(AllocateCodec.read(reader)?)),
            9 => Ok(SystemInstructionData::AllocateWithSeed(
                AllocateWithSeedCodec.read(reader)?,
            )),
            10 => Ok(SystemInstructionData::AssignWithSeed(
                AssignWithSeedCodec.read(reader)?,
            )),
            11 => Ok(SystemInstructionData::TransferSolWithSeed(
                TransferSolWithSeedCodec.read(reader)?,
            )),
            12 => Ok(SystemInstructionData::UpgradeNonceAccount(
                UpgradeNonceAccountCodec.read(reader)?,
            )),
            13 => Ok(SystemInstructionData::CreateAccountAllowPrefund(
                CreateAccountAllowPrefundCodec.read(reader)?,
            )),
            _ => Err(Error::InvalidDiscriminator),
        }
    }
}
